CommonData.BannerCustomCSS:
#onetrust-banner-sdk .ot-sdk-container {
  padding: 44px 48px !important;
  max-width: 1568px !important;
}

#onetrust-banner-sdk .ot-sdk-row {
  display: flex !important;
}

#onetrust-banner-sdk .ot-sdk-eight.ot-sdk-columns {
  width: auto !important;
}

#onetrust-banner-sdk #onetrust-button-group-parent {
  position: relative !important;
  height: 100% !important;
  width: auto !important;
  top: unset !important;
  left: unset !important;
  right: unset !important;
  bottom: unset !important;
  transform: none !important;
  max-width: none !important;
  flex-shrink: 0 !important;
  padding-right: 0 !important;
  padding-left: 2% !important;
  margin: auto !important;
}

#onetrust-banner-sdk #onetrust-policy-text {
  font-size: 12px !important;
  line-height: 16.2px !important;
  margin: 0 !important;
}

#onetrust-banner-sdk #onetrust-button-group {
  margin: auto !important;
}

#onetrust-banner-sdk #onetrust-button-group-parent button {
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  margin-right: 13px !important;
  display: inline-block !important;
  text-decoration: none !important;
  text-align: center !important;
  border-radius: 3.125rem !important;
  -webkit-border-radius: 3.125rem !important;
  -moz-border-radius: 3.125rem !important;
  font-weight: 700;
  background: #ffffff !important;
  border: none !important;
  vertical-align: middle !important;
  width: auto !important;
  cursor: pointer;
  overflow: visible !important;
  padding: 6.5px 21px !important;
  font-size: 14px !important;
  line-height: 21.73px !important;
  float: none !important;
}

#onetrust-banner-sdk #onetrust-button-group-parent button:hover {
  background-color: #f0f0f1 !important; //depending
  opacity: 1;
  text-decoration: none;
}

#onetrust-banner-sdk #onetrust-button-group-parent button:focus {
  background: #f0f0f1 !important;
  position: relative !important;
  outline: 0;
}

#onetrust-banner-sdk #onetrust-button-group-parent button:active {
  background: #f0f0f1 !important;
}

#onetrust-banner-sdk #onetrust-button-group-parent button:focus:after {
  content: '';
  position: absolute;
  top: -0.25rem;
  left: -0.25rem;
  right: -0.25rem;
  bottom: -0.25rem;
  -webkit-filter: blur(2px);
  filter: blur(2px);
  outline: 0.125rem solid #005695;
  border-radius: 3.125rem;
}

#onetrust-banner-sdk
  #onetrust-button-group-parent
  button:focus:not(:focus-visible):after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  outline: 0;
  -webkit-filter: none;
  filter: none;
}

#onetrust-banner-sdk
  #onetrust-button-group-parent
  button#onetrust-accept-btn-handler {
  margin-right: 0 !important;
}

#onetrust-banner-sdk #onetrust-policy {
  margin: 0 !important;
}

@media (max-width: 1023.98px) {
  #onetrust-banner-sdk .ot-sdk-container {
    padding: 44px !important;
  }

  #onetrust-banner-sdk .ot-sdk-row {
    display: block !important;
  }

  #onetrust-banner-sdk #onetrust-button-group-parent {
    padding-left: 0 !important;
  }

  #onetrust-banner-sdk #onetrust-policy-text {
    margin-bottom: 16px !important;
  }

  #onetrust-banner-sdk #onetrust-button-group {
    width: 100% !important;
    text-align: left !important;
  }
}

@media (max-width: 767.98px) {
  #onetrust-banner-sdk .ot-sdk-container {
    padding: 20px !important;
    padding-bottom: 4px !important;
  }

  #onetrust-banner-sdk #onetrust-button-group-parent button {
    margin-bottom: 16px !important;
  }

  #onetrust-pc-sdk .ot-btn-container {
    margin-bottom: 16px !important;
  }

  #onetrust-pc-sdk button.ot-pc-refuse-all-handler {
    margin-bottom: 0px !important;
  }

  #onetrust-pc-sdk button.save-preference-btn-handler {
    margin-bottom: 0px !important;
  }
}

#onetrust-pc-sdk .ot-cat-grp .ot-always-active {
  color: #ffffff !important;
}

#onetrust-pc-sdk .ot-plus-minus span {
  background: #ffffff !important;
}

#onetrust-pc-sdk button#accept-recommended-btn-handler,
#onetrust-pc-sdk button.ot-pc-refuse-all-handler,
#onetrust-pc-sdk button.save-preference-btn-handler {
  display: inline-block !important;
  text-decoration: none !important;
  text-align: center !important;
  border-radius: 3.125rem !important;
  -webkit-border-radius: 3.125rem !important;
  -moz-border-radius: 3.125rem !important;
  font-weight: 700;
  background: #ffffff !important;
  border: none !important;
  vertical-align: middle !important;
  width: auto !important;
  cursor: pointer;
  overflow: visible !important;
  padding: 6.5px 21px !important;
  font-size: 14px !important;
  line-height: 21.73px !important;
}

#onetrust-pc-sdk button#accept-recommended-btn-handler:hover,
#onetrust-pc-sdk button.ot-pc-refuse-all-handler:hover,
#onetrust-pc-sdk button.save-preference-btn-handler:hover {
  background-color: #f0f0f1 !important; //depending
  opacity: 1 !important;
  text-decoration: none !important;
}

#onetrust-pc-sdk button#accept-recommended-btn-handler:focus,
#onetrust-pc-sdk button.ot-pc-refuse-all-handler:focus,
#onetrust-pc-sdk button.save-preference-btn-handler:focus {
  background: #f0f0f1 !important;
  position: relative !important;
  outline: 0 !important;
}

#onetrust-pc-sdk button#accept-recommended-btn-handler:active,
#onetrust-pc-sdk button.ot-pc-refuse-all-handler:active,
#onetrust-pc-sdk button.save-preference-btn-handler:active {
  background: #f0f0f1 !important;
}

#onetrust-pc-sdk button#accept-recommended-btn-handler:focus:after,
#onetrust-pc-sdk button.ot-pc-refuse-all-handler:focus:after,
#onetrust-pc-sdk button.save-preference-btn-handler:focus:after {
  content: '' !important;
  position: absolute !important;
  top: -0.25rem !important;
  left: -0.25rem !important;
  right: -0.25rem !important;
  bottom: -0.25rem !important;
  -webkit-filter: blur(2px) !important;
  filter: blur(2px) !important;
  outline: 0.125rem solid #005695 !important;
  border-radius: 3.125rem !important;
}

#onetrust-pc-sdk
  button#accept-recommended-btn-handler:focus:not(:focus-visible):after,
#onetrust-pc-sdk
  button.ot-pc-refuse-all-handler:focus:not(:focus-visible):after,
#onetrust-pc-sdk
  button.save-preference-btn-handler:focus:not(:focus-visible):after {
  content: '' !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  outline: 0 !important;
  -webkit-filter: none !important;
  filter: none !important;
}

#onetrust-pc-sdk #close-pc-btn-handler.ot-close-icon {
  filter: brightness(3) !important;
}
